    static class TestPojo {
        @JacksonXmlProperty(isAttribute = true)
        public String id;

        @JacksonXmlText
        @JsonRawValue
        public String value;

        public TestPojo() { }
        public TestPojo(String id, String value) {
            this.id = id;
            this.value = value;
        }
    }

    @Test
    public void testRawValueUnwrappedWithJacksonXmlText() throws Exception {
        XmlMapper mapper = new XmlMapper();
        TestPojo pojo = new TestPojo("123", "<a>A</a><b someAttribute=\"B\">B</b>");
        String xml = mapper.writeValueAsString(pojo);

        // Verify root element and attribute
        assertTrue("Root element should be test-pojo", xml.contains("<test-pojo"));
        assertTrue("Attribute id should be 123", xml.contains("id=\"123\""));

        // Verify raw content is present
        assertTrue("Raw content <a> should be present", xml.contains("<a>A</a>"));
        assertTrue("Raw content <b> should be present", xml.contains("<b someAttribute=\"B\">B</b>"));

        // Verify NO wrapper element for 'value' field.
        // Before the patch, the output would contain <value>...</value> wrapping the raw content.
        // After the patch, @JacksonXmlText causes checkNextIsUnwrapped() to return true,
        // leading to direct writeRaw() without start/end element tags.
        assertFalse("Raw value should not be wrapped in <value> element when @JacksonXmlText is present", xml.contains("<value>"));
