public class JacksonXmlAnnotationIntrospectorNamespaceTest {

    private final JacksonXmlAnnotationIntrospector introspector = new JacksonXmlAnnotationIntrospector();
    private final MapperConfig<?> config = new XmlMapper().getSerializationConfig();

    // Test class: JacksonXmlProperty has empty namespace (default), JsonProperty has valid namespace
    public static class TestClassEmptyXmlNs {
        @JsonProperty(value = "value", namespace = "uri:ns1")
        @JacksonXmlProperty(isAttribute = true)
        public int valueDefault = 42;
    }

    // Test class: Both have valid namespaces, JacksonXmlProperty should take precedence
    public static class TestClassValidXmlNs {
        @JsonProperty(value = "value", namespace = "uri:ns2")
        @JacksonXmlProperty(namespace = "uri:ns1")
        public int valueWithNs = 42;
    }

    // Test class: Only JacksonXmlProperty annotation
    public static class TestClassOnlyXmlProp {
        @JacksonXmlProperty(namespace = "uri:xmlonly")
        public int value = 42;
    }

    // Test class: Only JsonProperty annotation
    public static class TestClassOnlyJsonProp {
        @JsonProperty(namespace = "uri:jsononly")
        public int value = 42;
    }

    // Test class: Both annotations present, but both have default empty namespace
    public static class TestClassEmptyXmlEmptyJson {
        @JacksonXmlProperty(isAttribute = true)
        @JsonProperty(value = "value")
        public int value = 42;
    }

    // Test class: No namespace annotations
    public static class TestClassNoNamespace {
        public int value = 42;
    }

    /**
     * Helper method to create AnnotatedField with properly populated AnnotationMap.
     * The original test failure was caused by an empty AnnotationMap, preventing
     * the introspector from finding the annotations on the field.
     */
    private AnnotatedField createAnnotatedField(Class<?> clazz, String fieldName) throws Exception {
        Field field = clazz.getDeclaredField(fieldName);
        AnnotationMap annMap = new AnnotationMap();
        // Populate the AnnotationMap with actual annotations from the field
        for (Annotation ann : field.getAnnotations()) {
            annMap.add(ann);
        }
        // TypeResolutionContext is null as findNamespace does not require type resolution
        return new AnnotatedField(null, field, annMap);
    }

    @Test
    public void testFindNamespace_EmptyXmlNs_ValidJsonNs() throws Exception {
        // Scenario: @JacksonXmlProperty namespace is empty (""), @JsonProperty namespace is "uri:ns1"
        // Expected: Should return @JsonProperty namespace because @JacksonXmlProperty is empty
        AnnotatedField annotatedField = createAnnotatedField(TestClassEmptyXmlNs.class, "valueDefault");
        String namespace = introspector.findNamespace(config, annotatedField);
        assertEquals("uri:ns1", namespace);
    }

    @Test
    public void testFindNamespace_ValidXmlNs_ValidJsonNs() throws Exception {
        // Scenario: Both have valid namespaces.
        // Expected: @JacksonXmlProperty takes precedence
        AnnotatedField annotatedField = createAnnotatedField(TestClassValidXmlNs.class, "valueWithNs");
        String namespace = introspector.findNamespace(config, annotatedField);
        assertEquals("uri:ns1", namespace);
    }

