    public void testFindNamespace_OnlyXmlProperty() throws Exception {
        // Scenario: Only @JacksonXmlProperty is present.
        // Expected: Return @JacksonXmlProperty namespace
        AnnotatedField annotatedField = createAnnotatedField(TestClassOnlyXmlProp.class, "value");
        String namespace = introspector.findNamespace(config, annotatedField);
        assertEquals("uri:xmlonly", namespace);
    }

    @Test
    public void testFindNamespace_OnlyJsonProperty() throws Exception {
        // Scenario: Only @JsonProperty is present.
        // Expected: Return @JsonProperty namespace (fallback)
        AnnotatedField annotatedField = createAnnotatedField(TestClassOnlyJsonProp.class, "value");
        String namespace = introspector.findNamespace(config, annotatedField);
        assertEquals("uri:jsononly", namespace);
    }

    @Test
    public void testFindNamespace_EmptyXmlNs_EmptyJsonNs() throws Exception {
        // Scenario: Both annotations present, but both have default empty namespace ("").
        // Expected: Return empty string (from JsonProperty fallback logic when XmlProperty is empty)
        AnnotatedField annotatedField = createAnnotatedField(TestClassEmptyXmlEmptyJson.class, "value");
        String namespace = introspector.findNamespace(config, annotatedField);
        assertEquals("", namespace);
    }

    @Test
    public void testFindNamespace_NoAnnotations() throws Exception {
        // Scenario: No annotations present.
        // Expected: Return null
        AnnotatedField annotatedField = createAnnotatedField(TestClassNoNamespace.class, "value");
        String namespace = introspector.findNamespace(config, annotatedField);
        assertNull(namespace);
    }
}

